head.script:
scwin.spinner1_onDownButtonClick = function() {};
scwin.spinner1_onUpButtonClick = function() {};
scwin.spinner2_onUpButtonClick = function() {};
scwin.spinner2_onDownButtonClick = function() {};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 위,아래버튼을 클릭한다.
    //1. After executing the sample file, click the up and down buttons.
    //Verify 1. 정상적으로 값이 변경되어진다.(이전에는 입력타입제약 알림메시지 발생)
    //1. The value is changed normally (previously, input type restriction notification message is generated)
    //spinner1_up
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('spinner1_upButton').click()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('spinner1___input').realValue == '2016/01/02 04'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //spinner1_down
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('spinner1_downButton').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('spinner1___input').realValue == '2016/01/02 03'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    spinner1.setValue("2016010203");
    spinner2.setValue("0102")
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 28-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
